const ledgerRows = $('Fetch Claims Ledger').all().map(i => i.json);

let text = String($('Extract Payment Results').first().json.data ?? '');
if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);

// Tolerant CSV parsing: handles quote-wrapped whole rows (Excel artifacts), blank lines, any line endings
function splitCsv(line) {
  const fields = [];
  let cur = '';
  let inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (inQ) {
      if (c === '\"') {
        if (line[i + 1] === '\"') { cur += '\"'; i++; } else { inQ = false; }
      } else { cur += c; }
    } else {
      if (c === '\"') { inQ = true; }
      else if (c === ',') { fields.push(cur); cur = ''; }
      else { cur += c; }
    }
  }
  fields.push(cur);
  return fields.map(f => f.trim());
}

const lines = text.split(/\r\n|\r|\n/).map(l => l.trim()).filter(l => l.length > 0);
const cleaned = [];
for (const l of lines) {
  let s = l;
  if (s.length > 1 && s.startsWith('\"') && s.endsWith('\"') && s.slice(1, -1).indexOf('\"') === -1) {
    s = s.slice(1, -1);
  }
  cleaned.push(s);
}
if (cleaned.length < 2) return [];

const header = splitCsv(cleaned[0]);
const results = [];
for (let li = 1; li < cleaned.length; li++) {
  const fields = splitCsv(cleaned[li]);
  if (fields.every(f => f === '')) continue;
  const row = {};
  for (let fi = 0; fi < header.length; fi++) { row[header[fi]] = fields[fi] ?? ''; }
  results.push(row);
}

const ledgerByRef = {};
for (const r of ledgerRows) { ledgerByRef[String(r.claim_reference).trim()] = r; }

const out = [];
for (const row of results) {
  // Tolerant header matching: works across portal results file layout variations
  const lookup = {};
  for (const k of Object.keys(row)) { lookup[k.toLowerCase().replace(/[^a-z0-9]/g, '')] = row[k]; }

  const claimRef = String(lookup.claimreference ?? lookup.claimref ?? '').trim();
  const statusRaw = String(lookup.status ?? lookup.outcome ?? lookup.paymentstatus ?? lookup.claimstatus ?? '').toLowerCase();
  const paidAmount = Number(String(lookup.paidamount ?? lookup.amountpaid ?? lookup.paid ?? '0').replace(/[^0-9.-]/g, '')) || 0;
  const reason = String(lookup.errormessage ?? lookup.rejectionreason ?? lookup.reason ?? lookup.comments ?? lookup.error ?? '').trim();

  let outcome = 'unknown';
  if (statusRaw.includes('reject') || statusRaw.includes('error') || statusRaw.includes('cancel') || statusRaw.includes('fail')) outcome = 'rejected';
  else if (statusRaw.includes('paid') || statusRaw.includes('approv') || statusRaw.includes('accept') || statusRaw.includes('success') || statusRaw.includes('complete')) outcome = 'paid';
  else if (paidAmount > 0) outcome = 'paid';

  const ledger = ledgerByRef[claimRef];

  out.push({ json: {
    claim_reference: claimRef || '(missing claim reference)',
    matched: !!ledger,
    outcome: outcome,
    paid_amount: outcome === 'paid' ? (paidAmount || Number(ledger ? ledger.total : 0) || 0) : 0,
    paid_date: outcome === 'paid' ? $today.toFormat('yyyy-MM-dd') : '',
    rejection_reason: outcome === 'rejected' ? (reason || 'No reason given in results file') : '',
    participant_name: ledger ? ledger.participant_name : '',
    claimed_total: ledger ? ledger.total : ''
  }});
}
return out;

const rows = $('Reconcile Results').all().map(i => i.json);
const paid = rows.filter(r => r.matched && r.outcome === 'paid');
const rejected = rows.filter(r => r.matched && r.outcome === 'rejected');
const problems = rows.filter(r => !r.matched || r.outcome === 'unknown');

let paidTotal = 0;
for (const p of paid) { paidTotal += Number(p.paid_amount) || 0; }
paidTotal = Math.round(paidTotal * 100) / 100;

let html = '<h2>NDIS payment results processed</h2>';
html += '<p><b>' + paid.length + '</b> claims paid totalling <b>$' + paidTotal.toFixed(2) + '</b> · <b>' + rejected.length + '</b> rejected · <b>' + problems.length + '</b> needing attention.</p>';

if (rejected.length) {
  html += '<h3>Rejected — resubmission queue</h3><table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Claim</th><th>Participant</th><th>Reason</th></tr>';
  for (const r of rejected) { html += '<tr><td>' + r.claim_reference + '</td><td>' + (r.participant_name || 'Unknown') + '</td><td>' + r.rejection_reason + '</td></tr>'; }
  html += '</table><p>These are flagged as rejected in the claims ledger. Fix the cause, then re-invoice in the PMS so they enter the next daily batch.</p>';
}

if (problems.length) {
  html += '<h3>Needs attention (unmatched or unclear outcome)</h3><table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Claim reference in file</th><th>Issue</th></tr>';
  for (const u of problems) { html += '<tr><td>' + u.claim_reference + '</td><td>' + (u.matched ? 'Outcome column unclear' : 'No matching claim in the ledger') + '</td></tr>'; }
  html += '</table>';
}

if (paid.length) {
  html += '<h3>Paid</h3><table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Claim</th><th>Participant</th><th>Paid</th></tr>';
  for (const p of paid) { html += '<tr><td>' + p.claim_reference + '</td><td>' + (p.participant_name || '') + '</td><td>$' + Number(p.paid_amount).toFixed(2) + '</td></tr>'; }
  html += '</table>';
}

return [{ json: { html: html, paid_count: paid.length, rejected_count: rejected.length, problem_count: problems.length, paid_total: paidTotal.toFixed(2) } }];
